<section class="page-header"><div><span class="eyebrow">Photo & geolocation attendance</span><h1>Daily Attendance</h1><p>Server-time records with location accuracy, distance and working duration.</p></div><div class="page-actions"><a class="button button-secondary" href="<?= url('reports?from='.$date.'&to='.$date) ?>"><i class="fa-solid fa-chart-line"></i> Report</a></div></section>
<div class="mini-metrics"><div><span>Present</span><strong><?= (int)($summary['Present']??0) ?></strong></div><div><span>Late</span><strong><?= (int)($summary['Late']??0) ?></strong></div><div><span>Half day</span><strong><?= (int)($summary['Half Day']??0) ?></strong></div><div><span>Absent</span><strong><?= (int)($summary['Absent']??0) ?></strong></div></div>
<section class="panel table-panel"><form class="filter-bar" method="get"><label><span>Attendance date</span><input type="date" name="date" value="<?= e($date) ?>"></label><button class="button button-secondary">View date</button><a class="button button-ghost" href="<?= url('reports/export?type=attendance&from='.$date.'&to='.$date) ?>">Export CSV</a></form><div class="table-scroll"><table class="data-table"><thead><tr><th>Employee</th><th>Status</th><th>Check-in</th><th>Check-out</th><th>Accuracy</th><th>Distance</th><th>Late</th><th>Worked</th><th>Photos</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?= e($row['name']) ?></strong><small class="cell-sub"><?= e($row['employee_code']) ?> · <?= e($row['department_name']?:'No department') ?></small></td><td><span class="status-badge <?= status_class($row['status']) ?>"><?= e($row['status']) ?></span></td><td><?= $row['check_in_at']?e(date('g:i A',strtotime($row['check_in_at']))):'—' ?></td><td><?= $row['check_out_at']?e(date('g:i A',strtotime($row['check_out_at']))):'—' ?></td><td><?= $row['location_accuracy']?'±'.number_format((float)$row['location_accuracy']).' m':'—' ?></td><td><?= $row['distance_from_office']?number_format((float)$row['distance_from_office']).' m':'—' ?></td><td><?= (int)$row['late_minutes'] ?> min</td><td><?= floor($row['working_minutes']/60).'h '.($row['working_minutes']%60).'m' ?></td><td><div class="photo-links"><?php if($row['check_in_photo']):?><a href="<?= url('attendance/photo/'.$row['id'].'/in') ?>" target="_blank" title="Check-in photo"><i class="fa-solid fa-camera"></i> In</a><?php endif;?><?php if($row['check_out_photo']):?><a href="<?= url('attendance/photo/'.$row['id'].'/out') ?>" target="_blank"><i class="fa-solid fa-camera"></i> Out</a><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9"><div class="empty-state"><span><i class="fa-solid fa-user-clock"></i></span><h3>No attendance records</h3><p>No one has punched attendance for this date.</p></div></td></tr><?php endif;?></tbody></table></div></section>
